    searchParams = new URLSearchParams('status=failed');
    render(<MediaQueue />);

    fireEvent.click(screen.getByRole('button', { name: 'All' }));

    expect(mockReplace).toHaveBeenCalledWith('/media/queue', { scroll: false });
