import 'reflect-metadata';
import { describe, it, expect, vi } from 'vitest';
import { ListMediaProvidersTool } from './media.providers.tool';
import { executeTool, makeOrganization, makeUser } from './__tests__/tool-test.harness';

describe('ListMediaProvidersTool', () => {
  const org = makeOrganization();
  const user = makeUser();

  const noDefaults = {
    getMediaDefaults: vi.fn().mockResolvedValue({ categories: [] }),
  };

  it('returns configured and enabled providers', async () => {
    const service = {
      getProviders: vi.fn().mockResolvedValue([
        {
          identifier: 'runway',
          name: 'Runway',
          capabilities: { video: true },
          enabled: true,
          isConfigured: true,
        },
        {
          identifier: 'luma',
          name: 'Luma',
          capabilities: { video: true },
          enabled: true,
          isConfigured: false,
        },
        {
          identifier: 'openai',
          name: 'OpenAI',
          capabilities: { image: true, audio: true },
          enabled: false,
          isConfigured: true,
        },
      ]),
    };
    const tool = new ListMediaProvidersTool(service as any, noDefaults as any);

    const result = await executeTool(tool, {
      inputData: {},
      organization: org,
      user,
      access: { mode: 'user' },
    });

    expect(Array.isArray(result)).toBe(true);
    expect(result).toHaveLength(1);
    expect(result[0]).toEqual({
      identifier: 'runway',
      name: 'Runway',
      capabilities: { video: true },
      defaults: [],
    });
  });

  it('attaches the org defaults for the provider and survives a defaults-service failure', async () => {
    const service = {
      getProviders: vi.fn().mockResolvedValue([
        {
          identifier: 'openrouter',
          name: 'OpenRouter',
          capabilities: { image: true },
          enabled: true,
          isConfigured: true,
        },
      ]),
    };
    const defaults = {
      getMediaDefaults: vi.fn().mockResolvedValue({
        categories: [
          { category: 'text-to-image', providerId: 'openrouter', model: 'google/gemini-2.5-flash-image' },
          { category: 'image-to-image', providerId: 'openrouter', model: 'google/gemini-2.5-flash-image' },
          { category: 'text-to-video', providerId: 'runway', model: 'gen4' },
          { category: 'text-to-speech', source: null },
        ],
      }),
    };
    const tool = new ListMediaProvidersTool(service as any, defaults as any);

    const result = await executeTool(tool, {
      inputData: {},
      organization: org,
      user,
      access: { mode: 'user' },
    });

    expect(result[0].defaults).toEqual([
      { category: 'text-to-image', model: 'google/gemini-2.5-flash-image' },
      { category: 'image-to-image', model: 'google/gemini-2.5-flash-image' },
    ]);

    const failing = { getMediaDefaults: vi.fn().mockRejectedValue(new Error('redis down')) };
    const tool2 = new ListMediaProvidersTool(service as any, failing as any);
    const result2 = await executeTool(tool2, {
      inputData: {},
      organization: org,
      user,
      access: { mode: 'user' },
    });
    expect(result2[0].defaults).toEqual([]);
  });

  it('denies read without access context', async () => {
    const tool = new ListMediaProvidersTool({ getProviders: vi.fn() } as any, noDefaults as any);

    await expect(
      executeTool(tool, { inputData: {}, organization: org, user })
    ).rejects.toThrow('Read access denied: no access context');
  });

  it('denies mcp read without mcp:read scope', async () => {
    const tool = new ListMediaProvidersTool({ getProviders: vi.fn() } as any, noDefaults as any);

    await expect(
      executeTool(tool, {
        inputData: {},
        organization: org,
        user,
        access: { mode: 'mcp', scopes: [] },
      })
    ).rejects.toThrow('Read access denied: mcp:read scope required');
  });
});

import 'reflect-metadata';
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';

import { AuthProviderManager } from './auth-provider.manager';

const ORIGINAL_ENV = { ...process.env };

// Every env var the getProviders env fallback can key on. Fallback tests must
// start from a clean slate so developer-machine / CI env cannot leak providers
// into the advertised list.
const PROVIDER_ENV_VARS = [
  'IS_GENERAL',
  'POSTMILL_GENERIC_OAUTH',
  'POSTMILL_OAUTH_CLIENT_ID',
  'POSTMILL_OAUTH_CLIENT_SECRET',
  'POSTMILL_OAUTH_AUTH_URL',
  'POSTMILL_OAUTH_TOKEN_URL',
  'POSTMILL_OAUTH_USERINFO_URL',
  'NEXT_PUBLIC_POSTMILL_OAUTH_DISPLAY_NAME',
  'YOUTUBE_CLIENT_ID',
  'YOUTUBE_CLIENT_SECRET',
  'GITHUB_CLIENT_ID',
  'GITHUB_CLIENT_SECRET',
  'NEYNAR_CLIENT_ID',
  'STRIPE_PUBLISHABLE_KEY',
  'FACEBOOK_SSO_ENABLED',
  'FACEBOOK_APP_ID',
  'FACEBOOK_APP_SECRET',
  'X_SSO_ENABLED',
  'X_API_KEY',
  'X_API_SECRET',
  'X_CLIENT_ID',
  'X_CLIENT_SECRET',
  'LINKEDIN_SSO_ENABLED',
  'LINKEDIN_CLIENT_ID',
  'LINKEDIN_CLIENT_SECRET',
  'APPLE_SSO_ENABLED',
  'APPLE_CLIENT_ID',
  'APPLE_TEAM_ID',
  'APPLE_KEY_ID',
  'APPLE_PRIVATE_KEY',
];

function clearProviderEnv() {
  for (const key of PROVIDER_ENV_VARS) {
    delete process.env[key];
  }
}

function setGenericOauthEnv() {
  process.env.POSTMILL_OAUTH_CLIENT_ID = 'oidc-id';
  process.env.POSTMILL_OAUTH_CLIENT_SECRET = 'oidc-secret';
  process.env.POSTMILL_OAUTH_AUTH_URL = 'https://idp.example.com/authorize';
  process.env.POSTMILL_OAUTH_TOKEN_URL = 'https://idp.example.com/token';
  process.env.POSTMILL_OAUTH_USERINFO_URL = 'https://idp.example.com/userinfo';
}

function makeManager(overrides: {
  kernel?: Partial<{
    latestActive: (...args: any[]) => any;
    versions: (...args: any[]) => any;
    resolveForRead: (...args: any[]) => any;
  }>;
  repo?: Partial<{ list: (...args: any[]) => any }>;
  runtimeContext?: Partial<{ build: (...args: any[]) => any }>;
}) {
  const kernel = {
    latestActive: vi.fn().mockReturnValue(undefined),
    versions: vi.fn().mockReturnValue([]),
    resolveForRead: vi.fn().mockReturnValue({
      create: vi.fn().mockReturnValue({ mocked: 'provider' }),
    }),
    ...overrides.kernel,
  };

  const repo = {
    list: vi.fn().mockResolvedValue([]),
    ...overrides.repo,
  };

  const runtimeContext = {
    build: vi.fn().mockReturnValue({ mocked: 'ctx' }),
    ...overrides.runtimeContext,
  };

  const manager = new AuthProviderManager(
    kernel as any,
    runtimeContext as any,
    repo as any
  );

  return { manager, kernel, repo, runtimeContext };
}

beforeEach(() => {
  vi.clearAllMocks();
});

afterEach(() => {
  process.env = { ...ORIGINAL_ENV };
});

describe('AuthProviderManager', () => {
  describe('getProviders', () => {
    it('overlays enabled DB providers onto the env list (LOCAL always present)', async () => {
      clearProviderEnv();
      const { manager, kernel, repo } = makeManager({
        repo: {
          list: vi.fn().mockResolvedValue([
            {
              provider: 'GOOGLE',
              enabled: true,
              displayName: 'Workspace SSO',
            },
            { provider: 'GITHUB', enabled: false, displayName: null },
            { provider: 'GENERIC', enabled: true, displayName: null },
          ]),
        },
        kernel: {
          latestActive: vi.fn().mockReturnValue({
            manifest: { version: 'v2', status: 'active' },
          }),
        },
      });

      const result = await manager.getProviders();

      expect(repo.list).toHaveBeenCalled();
      expect(result.providers).toEqual([
        { provider: 'LOCAL', displayName: 'Email', version: 'v2', status: 'active' },
        { provider: 'GOOGLE', displayName: 'Workspace SSO', version: 'v2', status: 'active' },
        { provider: 'GENERIC', displayName: 'OIDC', version: 'v2', status: 'active' },
      ]);
    });

    it('merges DB rows with env providers: DB wins per provider, env-only providers stay listed', async () => {
      clearProviderEnv();
      process.env.YOUTUBE_CLIENT_ID = 'yt-id';
      process.env.YOUTUBE_CLIENT_SECRET = 'yt-secret';
      process.env.FACEBOOK_SSO_ENABLED = 'true';
