    it('continues without failing when classification throws', async () => {
      defaultsResolution.resolve.mockResolvedValue({
        providerId: 'openai',
        version: 'v1',
        model: 'gpt-4.1',
      });
      classifyRepo.getUnclassifiedComments.mockRejectedValue(
        new Error('db down'),
      );

      await expect(
        classifyService.classifyPostComments('org-1', makePost()),
      ).resolves.toBeUndefined();

      expect(classifyRepo.updateSentimentForIds).not.toHaveBeenCalled();
    });

    it('does not re-classify already-classified comments (idempotent via NULL filter)', async () => {
      defaultsResolution.resolve.mockResolvedValue({
        providerId: 'openai',
        version: 'v1',
        model: 'gpt-4.1',
      });
      classifyRepo.getUnclassifiedComments.mockResolvedValue([]);

      await classifyService.classifyPostComments('org-1', makePost());

      expect(aiModelProvider.generateObjectWithModel).not.toHaveBeenCalled();
      expect(classifyRepo.updateSentimentForIds).not.toHaveBeenCalled();
    });
  });
});

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { mkdtempSync, writeFileSync, rmSync } from 'fs';
import { tmpdir } from 'os';
import { join } from 'path';
import {
  runDomainConformance,
  LoggerPort,
  ProviderRuntimeContext,
  SafeFetchPort,
} from '@postmill-ai/provider-kernel';
import defaultModules from '../..';
import { medialockerStorageModule } from '../storage.adapter';

const API = 'https://api.medialocker.io';
const BUCKET_ID = 'bucket-uuid-1';
const CREDS = { apiKey: 'secret-key', bucketId: BUCKET_ID };

const logger: LoggerPort = {
  log: vi.fn(),
  warn: vi.fn(),
  error: vi.fn(),
  debug: vi.fn(),
};

const jsonResponse = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body), {
    status,
    headers: { 'Content-Type': 'application/json' },
  });

const makeCtx = (
  fetchMock: SafeFetchPort,
  credentials: Record<string, string> = CREDS,
  extras?: Record<string, unknown>,
): ProviderRuntimeContext => ({
  credentials,
  encryption: {
    encrypt: (v) => v,
    decrypt: (v) => v,
  },
  fetch: fetchMock,
  logger,
  telemetry: { recordCall: vi.fn() },
  extras,
});

// Minimal PNG (magic bytes + IHDR start) so file-type sniffs image/png.
const PNG = Buffer.from([
  0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a, 0x00, 0x00, 0x00, 0x0d, 0x49,
  0x48, 0x44, 0x52, 0x00, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00, 0x01, 0x08, 0x06,
  0x00, 0x00, 0x00,
]);

describe('medialocker provider conformance', () => {
  it('storage module conforms (create() never throws, even with empty creds)', () => {
    const storage = defaultModules.find((m) => m.manifest.domain === 'storage');
    expect(storage).toBeDefined();
    runDomainConformance('storage', storage!, {
      requiredMethods: [
        'uploadSimple',
        'uploadFile',
        'removeFile',
        'testConnection',
        'listFiles',
        'getFileUrl',
        'deleteFile',
        'getUsageBytes',
        'writeBuffer',
        'readFile',
      ],
    });
  });

  it('throws a clear error on first use without credentials', () => {
    const cap = medialockerStorageModule.create(makeCtx(vi.fn() as any, {}));
    expect(() => cap.listFiles()).toThrow(
      'Missing or invalid credential "Secret Access Key" (apiKey) for MEDIALOCKER',
    );
  });

  it('requires bucketId as well', () => {
    const cap = medialockerStorageModule.create(
      makeCtx(vi.fn() as any, { apiKey: 'k' }),
    );
    expect(() => cap.listFiles()).toThrow(
      'Missing or invalid credential "Bucket ID" (bucketId) for MEDIALOCKER',
    );
  });
});

describe('MediaLockerStorage', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe('writeBuffer upload flow', () => {
    it('presigns, PUTs with the signed headers verbatim, confirms, and returns the key', async () => {
      const fetchMock = vi.fn(async (input: any, init?: RequestInit) => {
        const url = String(input);
        if (url === `${API}/api/presign/upload`) {
          const sent = JSON.parse(String(init?.body));
          return jsonResponse({
            url: 'https://uploads.medialocker.io/signed-put',
            method: 'PUT',
            key: sent.key,
            bucketId: BUCKET_ID,
            bucket: 'media-bucket',
            expiresIn: 900,
            headers: { 'x-amz-meta-sha': 'abc123', 'Content-Type': 'image/png' },
          });
        }
        if (url === 'https://uploads.medialocker.io/signed-put') {
          return new Response(null, { status: 200 });
        }
        if (url === `${API}/api/presign/confirm`) {
          return jsonResponse({});
        }
        throw new Error(`unexpected fetch: ${url}`);
      });

      const cap = medialockerStorageModule.create(makeCtx(fetchMock as any));
      const key = await cap.writeBuffer(PNG, 'image/png');

      expect(key).toMatch(/^[0-9a-f]{16}\.png$/);
      expect(fetchMock).toHaveBeenCalledTimes(3);

      const [presignUrl, presignInit] = fetchMock.mock.calls[0];
      expect(String(presignUrl)).toBe(`${API}/api/presign/upload`);
      expect(presignInit?.method).toBe('POST');
      expect((presignInit?.headers as any).Authorization).toBe(
        'Bearer secret-key',
      );
      expect(JSON.parse(String(presignInit?.body))).toEqual({
        bucketId: BUCKET_ID,
        key,
        contentType: 'image/png',
        size: PNG.length,
      });

      const [putUrl, putInit] = fetchMock.mock.calls[1];
      expect(String(putUrl)).toBe('https://uploads.medialocker.io/signed-put');
      expect(putInit?.method).toBe('PUT');
      expect(putInit?.headers).toEqual({
        'x-amz-meta-sha': 'abc123',
        'Content-Type': 'image/png',
      });
      expect(putInit?.body).toBe(PNG);

      const [confirmUrl, confirmInit] = fetchMock.mock.calls[2];
      expect(String(confirmUrl)).toBe(`${API}/api/presign/confirm`);
      expect(confirmInit?.method).toBe('POST');
      expect(JSON.parse(String(confirmInit?.body))).toEqual({
        bucketId: BUCKET_ID,
        key,
      });
    });
  });

  describe('uploadFile', () => {
    // `/files/upload-server` uses multer diskStorage (file.path, no buffer);
    // sniffing only the buffer made every such upload fail on MediaLocker orgs.
    const presignFlow = () =>
      vi.fn(async (input: any, init?: RequestInit) => {
        const url = String(input);
        if (url === `${API}/api/presign/upload`) {
          const sent = JSON.parse(String(init?.body));
          return jsonResponse({
            url: 'https://uploads.medialocker.io/signed-put',
            method: 'PUT',
            key: sent.key,
            bucketId: BUCKET_ID,
            bucket: 'media-bucket',
            expiresIn: 900,
            headers: { 'Content-Type': sent.contentType },
          });
        }
        if (url === 'https://uploads.medialocker.io/signed-put') {
          return new Response(null, { status: 200 });
        }
        if (url === `${API}/api/presign/confirm`) {
          return jsonResponse({});
        }
        throw new Error(`unexpected fetch: ${url}`);
      });

    it('uploads from a disk path when there is no buffer (upload-server)', async () => {
      const dir = mkdtempSync(join(tmpdir(), 'ml-upload-'));
      const filePath = join(dir, 'upload.tmp');
      writeFileSync(filePath, PNG);

      try {
        const fetchMock = presignFlow();
        const cap = medialockerStorageModule.create(makeCtx(fetchMock as any));
        const result = await cap.uploadFile({ path: filePath, size: PNG.length });

        expect(result.mimetype).toBe('image/png');
        expect(result.filename).toMatch(/\.png$/);
        // The disk bytes (not an undefined buffer) went out on the signed PUT.
        const putInit = fetchMock.mock.calls[1][1];
        expect(Buffer.isBuffer(putInit?.body)).toBe(true);
        expect((putInit?.body as Buffer).equals(PNG)).toBe(true);
      } finally {
        rmSync(dir, { recursive: true, force: true });
      }
    });

    it('rejects a file with neither a buffer nor a path', async () => {
      const fetchMock = presignFlow();
      const cap = medialockerStorageModule.create(makeCtx(fetchMock as any));
      await expect(cap.uploadFile({ size: 10 })).rejects.toThrow(
        'Invalid file upload.'
      );
      expect(fetchMock).not.toHaveBeenCalled();
    });
  });

  describe('readFile', () => {
    it('resolves key→objectId, presigns a download and GETs the signed url', async () => {
      const payload = Buffer.from('image-bytes');
      const fetchMock = vi.fn(async (input: any, init?: RequestInit) => {
        const url = String(input);
        if (url.startsWith(`${API}/api/media?`)) {
          return jsonResponse({
            data: [
              { id: 'obj-1', key: 'abc.png' },
              { id: 'obj-2', key: 'abc.png.bak' },
            ],
            total: 2,
            hasMore: false,
          });
        }
        if (url === `${API}/api/presign/download`) {
          return jsonResponse({
            url: 'https://downloads.medialocker.io/signed-get',
            method: 'GET',
            objectId: 'obj-1',
            key: 'abc.png',
            expiresIn: 900,
          });
        }
        if (url === 'https://downloads.medialocker.io/signed-get') {
          return new Response(payload, { status: 200 });
        }
        throw new Error(`unexpected fetch: ${url}`);
      });

      const cap = medialockerStorageModule.create(makeCtx(fetchMock as any));
      const out = await cap.readFile('abc.png');

      expect(out.equals(payload)).toBe(true);
      expect(fetchMock).toHaveBeenCalledTimes(3);
      expect((fetchMock.mock.calls[0][1]?.headers as any).Authorization).toBe(
        'Bearer secret-key',
      );
      // substring siblings must not match — exact key only
      expect(JSON.parse(String(fetchMock.mock.calls[1][1]?.body))).toEqual({
        objectId: 'obj-1',
      });
    });

    it('fetches the public URL directly when publicUrl is configured', async () => {
      const payload = Buffer.from('public-bytes');
      const fetchMock = vi.fn<SafeFetchPort>(
        async () => new Response(payload, { status: 200 }),
      );
      const cap = medialockerStorageModule.create(
        makeCtx(fetchMock as any, CREDS, { publicUrl: 'https://cdn.example.com' }),
      );

      const out = await cap.readFile('abc.png');

      expect(out.equals(payload)).toBe(true);
      expect(fetchMock).toHaveBeenCalledTimes(1);
      expect(String(fetchMock.mock.calls[0][0])).toBe(
        'https://cdn.example.com/abc.png',
      );
    });
  });

  describe('getFileUrl', () => {
    it('joins publicUrl when configured', () => {
      const cap = medialockerStorageModule.create(
        makeCtx(vi.fn() as any, CREDS, { publicUrl: 'https://cdn.example.com' }),
      );
      expect(cap.getFileUrl('k.png')).toBe('https://cdn.example.com/k.png');
    });

    it('presigns a download URL when no publicUrl is configured', async () => {
      const fetchMock = vi.fn(async (input: any) => {
        const url = String(input);
        if (url.startsWith(`${API}/api/media?`)) {
          return jsonResponse({
            data: [{ id: 'obj-1', key: 'k.png' }],
            total: 1,
            hasMore: false,
          });
        }
        if (url === `${API}/api/presign/download`) {
          return jsonResponse({
            url: 'https://downloads.medialocker.io/signed',
            method: 'GET',
            objectId: 'obj-1',
            key: 'k.png',
            expiresIn: 900,
          });
        }
        throw new Error(`unexpected fetch: ${url}`);
      });

      const cap = medialockerStorageModule.create(makeCtx(fetchMock as any));
      await expect(cap.getFileUrl('k.png')).resolves.toBe(
        'https://downloads.medialocker.io/signed',
      );
    });

    it('prefers ctx.extras.publicUrl over credentials publicUrl (AUD-2)', () => {
      const cap = medialockerStorageModule.create(
        makeCtx(
          vi.fn() as any,
          { ...CREDS, publicUrl: 'https://cred.example.com' },
          { publicUrl: 'https://extras.example.com' },
        ),
      );
      expect(cap.getFileUrl('k.png')).toBe('https://extras.example.com/k.png');
    });

    it('falls back to credentials publicUrl when extras has none (AUD-2)', () => {
      const cap = medialockerStorageModule.create(
        makeCtx(vi.fn() as any, { ...CREDS, publicUrl: 'https://cred.example.com' }),
      );
      expect(cap.getFileUrl('k.png')).toBe('https://cred.example.com/k.png');
    });
  });

  describe('listFiles', () => {
    it('maps defensive field variants and paginates via offset/hasMore', async () => {
      const fetchMock = vi.fn(async (input: any) => {
        const url = String(input);
        if (!url.startsWith(`${API}/api/media?`)) {
          throw new Error(`unexpected fetch: ${url}`);
        }
        const offset = new URL(url).searchParams.get('offset');
        if (offset === '0') {
          return jsonResponse({
            data: [
              {
                id: '1',
                objectId: 'o1',
                key: 'a.png',
                size: '123',
                created_at: '2026-01-01T00:00:00.000Z',
                contentType: 'image/png',
              },
              {
                objectId: 'o2',
                key: 'b.jpg',
                size: 456,
                createdAt: '2026-02-01T00:00:00.000Z',
                mimeType: 'image/jpeg',
              },
              { id: '3', key: 'c.gif', lastModified: '2026-03-01T00:00:00.000Z' },
              { id: '4', key: 'folder/' },
            ],
            total: 5,
            hasMore: true,
          });
        }
        return jsonResponse({
          data: [
            {
              id: '5',
              key: 'd.webp',
              size: 10,
              createdAt: '2026-04-01T00:00:00.000Z',
              contentType: 'image/webp',
            },
          ],
          total: 5,
          hasMore: false,
        });
      });

      const cap = medialockerStorageModule.create(makeCtx(fetchMock as any));
      const entries = await cap.listFiles('a');

      expect(fetchMock).toHaveBeenCalledTimes(2);
      const firstUrl = new URL(String(fetchMock.mock.calls[0][0]));
      expect(firstUrl.searchParams.get('bucketId')).toBe(BUCKET_ID);
      expect(firstUrl.searchParams.get('search')).toBe('a');
      expect(new URL(String(fetchMock.mock.calls[1][0])).searchParams.get('offset')).toBe('4');

      expect(entries).toHaveLength(4);
      expect(entries[0]).toEqual({
        key: 'a.png',
        name: 'a.png',
        size: 123,
        mimeType: 'image/png',
        lastModified: new Date('2026-01-01T00:00:00.000Z'),
      });
      expect(entries[1]).toEqual({
        key: 'b.jpg',
        name: 'b.jpg',
        size: 456,
        mimeType: 'image/jpeg',
        lastModified: new Date('2026-02-01T00:00:00.000Z'),
      });
      expect(entries[2].size).toBe(0);
      expect(entries[2].mimeType).toBe('');
      expect(entries[2].lastModified).toEqual(new Date('2026-03-01T00:00:00.000Z'));
      expect(entries[3].key).toBe('d.webp');
    });
  });

  describe('deleteFile / removeFile', () => {
    it('resolves the key to an objectId and DELETEs it', async () => {
      const fetchMock = vi.fn(async (input: any, init?: RequestInit) => {
        const url = String(input);
        if (url.startsWith(`${API}/api/media?`)) {
          return jsonResponse({
            data: [{ objectId: 'o9', key: 'dead.png' }],
            total: 1,
            hasMore: false,
          });
        }
        if (url === `${API}/api/media/o9`) {
          expect(init?.method).toBe('DELETE');
          return new Response(null, { status: 200 });
        }
        throw new Error(`unexpected fetch: ${url}`);
      });

      const cap = medialockerStorageModule.create(makeCtx(fetchMock as any));
      await cap.deleteFile('dead.png');

      expect(fetchMock).toHaveBeenCalledTimes(2);
      expect(String(fetchMock.mock.calls[1][0])).toBe(`${API}/api/media/o9`);
    });

    it('removeFile extracts the key from a URL first', async () => {
      const fetchMock = vi.fn(async (input: any) => {
        const url = String(input);
        if (url.startsWith(`${API}/api/media?`)) {
          return jsonResponse({
            data: [{ id: 'o7', key: 'dead.png' }],
            total: 1,
            hasMore: false,
          });
        }
        return new Response(null, { status: 200 });
      });

      const cap = medialockerStorageModule.create(makeCtx(fetchMock as any));
      await cap.removeFile('https://cdn.example.com/dead.png?x=1');

      expect(String(fetchMock.mock.calls[1][0])).toBe(`${API}/api/media/o7`);
    });

    it('throws a clear error when the key does not exist', async () => {
      const fetchMock = vi.fn(async () =>
        jsonResponse({ data: [], total: 0, hasMore: false }),
      );

      const cap = medialockerStorageModule.create(makeCtx(fetchMock as any));
      await expect(cap.deleteFile('missing.png')).rejects.toThrow(
        'MediaLocker object not found for key "missing.png"',
      );
    });
  });

  describe('getUsageBytes', () => {
    it('returns usedStorage as a BigInt', async () => {
      const fetchMock = vi.fn<SafeFetchPort>(async () =>
        jsonResponse({
          usedStorage: 10737418240,
          allocatedStorage: 1099511627776,
          egressThisMonth: 0,
          apiCallsThisMonth: 3,
          objectCount: 9,
        }),
      );

      const cap = medialockerStorageModule.create(makeCtx(fetchMock as any));
      expect(await cap.getUsageBytes()).toBe(BigInt(10737418240));
      expect(String(fetchMock.mock.calls[0][0])).toBe(`${API}/api/usage`);
    });

    it('returns null on failure', async () => {
      const fetchMock = vi.fn(async () => {
        throw new Error('network down');
      });

      const cap = medialockerStorageModule.create(makeCtx(fetchMock as any));
      expect(await cap.getUsageBytes()).toBeNull();
    });
  });

  describe('testConnection', () => {
    it('returns ok:true when /api/me succeeds', async () => {
      const fetchMock = vi.fn<SafeFetchPort>(async () =>
        jsonResponse({ id: 'user-1' }),
      );

      const cap = medialockerStorageModule.create(
        makeCtx(fetchMock as any, CREDS, { publicUrl: 'https://cdn.example.com' }),
      );
      await expect(cap.testConnection()).resolves.toEqual({ ok: true });
      expect(String(fetchMock.mock.calls[0][0])).toBe(`${API}/api/me`);
    });

    it('fails loudly without a publicUrl — persisted refs would be bare keys', async () => {
      // Without a public base, stableRef stores a bare object key, which fails
      // the designer-doc src schema. The config test must refuse the config
      // instead of letting it save dead references — and never hit the API.
      const fetchMock = vi.fn<SafeFetchPort>(async () => jsonResponse({ id: 'user-1' }));

      const cap = medialockerStorageModule.create(makeCtx(fetchMock as any));
      const res = await cap.testConnection();
      expect(res.ok).toBe(false);
      expect(res.error).toContain('Public URL');
      expect(fetchMock).not.toHaveBeenCalled();
    });

    it('returns ok:false with the envelope message on 401', async () => {
      const fetchMock = vi.fn(async () =>
        jsonResponse(
          { error: { code: 'UNAUTHORIZED', message: 'Invalid API key' } },
          401,
        ),
      );

      const cap = medialockerStorageModule.create(
        makeCtx(fetchMock as any, CREDS, { publicUrl: 'https://cdn.example.com' }),
      );
      const res = await cap.testConnection();
      expect(res.ok).toBe(false);
      expect(res.error).toBe('Invalid API key');
    });

    it('tolerates the Fastify 429 envelope', async () => {
      const fetchMock = vi.fn(async () =>
        jsonResponse(
          {
            statusCode: 429,
            error: 'Too Many Requests',
            message: 'Rate limit exceeded',
          },
          429,
        ),
      );

      const cap = medialockerStorageModule.create(
        makeCtx(fetchMock as any, CREDS, { publicUrl: 'https://cdn.example.com' }),
      );
      const res = await cap.testConnection();
      expect(res.ok).toBe(false);
      expect(res.error).toBe('Rate limit exceeded');
    });

    it('returns ok:false on network error', async () => {
      const fetchMock = vi.fn(async () => {
        throw new Error('ECONNREFUSED');
      });

      const cap = medialockerStorageModule.create(
        makeCtx(fetchMock as any, CREDS, { publicUrl: 'https://cdn.example.com' }),
      );
      const res = await cap.testConnection();
      expect(res.ok).toBe(false);
      expect(res.error).toContain('ECONNREFUSED');
    });
  });
});

import { test, expect, type BrowserContext, type Locator, type Page } from '@playwright/test';

const LIVE_CASES = ['studio-completed-video', 'designer-saved-video'] as const;
const liveMedia = process.env.E2E_LIVE_MEDIA === '1';
const liveCase = process.env.E2E_LIVE_CASE;

if (liveMedia && liveCase && !LIVE_CASES.includes(liveCase as (typeof LIVE_CASES)[number])) {
  throw new Error(`Unknown E2E_LIVE_CASE. Expected one of: ${LIVE_CASES.join(', ')}`);
}

test.skip(!liveMedia || !liveCase, 'Requires both E2E_LIVE_MEDIA=1 and a per-case E2E_LIVE_CASE');

function requiredEnv(name: string): string {
  const value = process.env[name]?.trim();
  if (!value) throw new Error(`${name} is required for E2E_LIVE_CASE=${liveCase}`);
  return value;
}

function sanitizedError(value: unknown): string | undefined {
  if (typeof value !== 'string' || !value) return undefined;
  return value
    .replace(/https?:\/\/\S+/gi, '[redacted-url]')
    .replace(/\b(bearer|authorization|api[_-]?key|token)\b\s*[:=]?\s*\S+/gi, '$1 [redacted]')
    .slice(0, 300);
}

async function blockPaidGeneration(context: BrowserContext): Promise<string[]> {
  const blocked: string[] = [];
  await context.route('**/*', async (route) => {
    const request = route.request();
    const pathname = new URL(request.url()).pathname;
    if (
      request.method() === 'POST' &&
      (/^\/(api\/)?media\/studio\/[^/]+\/generate$/.test(pathname) ||
        /^\/(api\/)?media\/generate-/.test(pathname) ||
        /^\/(api\/)?media\/replicate\/run\//.test(pathname) ||
        /^\/(api\/)?media\/(text-to-speech|heygen\/talking-photo)$/.test(pathname))
    ) {
      blocked.push(pathname);
      await route.fulfill({
        status: 503,
        contentType: 'application/json',
        body: JSON.stringify({ message: 'Generation is blocked in the live playback suite' }),
      });
      return;
    }
    await route.continue();
  });
  return blocked;
}

async function artifactMetadata(video: Locator) {
  return video.evaluate((element: HTMLVideoElement) => ({
    width: element.videoWidth,
    height: element.videoHeight,
    durationMs: Math.round(element.duration * 1000),
  }));
}

function logArtifact(
  provider: string,
  model: string | null,
  status: string | null,
  artifact?: { width: number; height: number; durationMs: number },
  error?: string
) {
  console.log(
    `[live-media] ${JSON.stringify({ provider, model, ...(status ? { status } : {}), ...(artifact ? { artifact } : {}), ...(error ? { error } : {}) })}`
  );
}

async function expectDecodeAdvanceAndSeek(page: Page | Locator, designer = false) {
  const video = page.locator('video').first();
  await expect.poll(() => video.evaluate((element: HTMLVideoElement) => element.readyState)).toBeGreaterThanOrEqual(2);
  const metadata = await artifactMetadata(video);
  expect(metadata.width).toBeGreaterThan(0);
  expect(metadata.height).toBeGreaterThan(0);
  expect(metadata.durationMs).toBeGreaterThan(0);

  const before = await video.evaluate((element: HTMLVideoElement) => element.currentTime);
  if (designer) {
    await page.getByRole('button', { name: 'Play', exact: true }).click();
  } else {
    await video.click();
    await video.evaluate((element: HTMLVideoElement) => element.play());
  }
  await expect.poll(() => video.evaluate((element: HTMLVideoElement) => element.currentTime)).toBeGreaterThan(before + 0.25);

  if (designer) {
    await page.getByRole('button', { name: 'Pause', exact: true }).click();
    const seek = page.getByRole('slider', { name: 'Seek timeline', exact: true });
    await seek.press('Home');
    await seek.press('ArrowRight');
  } else {
    await video.evaluate((element: HTMLVideoElement) => {
      element.pause();
      element.currentTime = Math.min(1, element.duration / 2);
    });
  }
  await expect.poll(() => video.evaluate((element: HTMLVideoElement) => element.currentTime)).toBeGreaterThan(0);
  return metadata;
}

test.describe('Opt-in live provider media playback', () => {
  test('an existing completed studio job plays and opens in Designer without generation', async ({ page, context }) => {
    test.skip(liveCase !== 'studio-completed-video', 'Select with E2E_LIVE_CASE=studio-completed-video');
    const provider = requiredEnv('E2E_LIVE_PROVIDER');
    if (!/^[a-z0-9-]+$/.test(provider)) throw new Error('E2E_LIVE_PROVIDER must be a studio identifier');
    const jobId = requiredEnv('E2E_LIVE_JOB_ID');
    const blocked = await blockPaidGeneration(context);
    const jobsResponse = page.waitForResponse(
      (response) =>
        response.request().method() === 'GET' &&
        /\/media\/studio\/[^/]+\/jobs$/.test(new URL(response.url()).pathname) &&
        response.status() === 200
    );

    await page.goto(`/media/${provider}`, { waitUntil: 'domcontentloaded' });
    const payload: unknown = await (await jobsResponse).json();
    const jobs = Array.isArray(payload) ? (payload as Array<Record<string, unknown>>) : [];
    const job = jobs.find((candidate) => candidate.id === jobId);
    expect(job, 'the selected job must be visible in this provider studio').toBeTruthy();
    const status = typeof job.status === 'string' ? job.status : 'unknown';
    const model = typeof job.model === 'string' ? job.model : null;
    logArtifact(provider, model, status, undefined, sanitizedError(job.error));
    expect(status).toBe('completed');
    expect(Boolean(job.artifactUrl), 'the completed job must have a stored artifact').toBe(true);

    const card = page.locator(`[id=${JSON.stringify(`media-job-${jobId}`)}]`);
    await expect(card.getByLabel('Generated video preview', { exact: true })).toBeVisible();
    const queueMetadata = await expectDecodeAdvanceAndSeek(card);
    logArtifact(provider, model, status, queueMetadata);

    const popup = page.waitForEvent('popup');
    await card.getByRole('button', { name: 'Edit in Designer', exact: true }).click();
    const designer = await popup;
    await designer.waitForLoadState('domcontentloaded');
    await expect(designer.getByRole('slider', { name: 'Clip', exact: true })).toHaveCount(1, { timeout: 90_000 });
    const designerMetadata = await expectDecodeAdvanceAndSeek(designer, true);
    logArtifact(provider, model, status, designerMetadata);
    expect(blocked, 'the live playback suite must never submit generation').toEqual([]);
  });

  test('an existing saved Designer video plays and seeks without generation', async ({ page, context }) => {
    test.skip(liveCase !== 'designer-saved-video', 'Select with E2E_LIVE_CASE=designer-saved-video');
    const designId = requiredEnv('E2E_LIVE_DESIGN_ID');
    const blocked = await blockPaidGeneration(context);
    await page.goto(`/media/designer?designId=${encodeURIComponent(designId)}`, { waitUntil: 'domcontentloaded' });
    await expect(page.getByRole('slider', { name: 'Clip', exact: true }).first()).toBeVisible({ timeout: 90_000 });
    const metadata = await expectDecodeAdvanceAndSeek(page, true);
    logArtifact('designer', null, null, metadata);
    expect(blocked, 'Designer playback must not submit generation').toEqual([]);
  });
});

import 'reflect-metadata';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { DesignRenderService } from '@postmill-ai/nestjs-libraries/media/design-render/design-render.service';
import type { DesignerDoc } from '@postmill-ai/nestjs-libraries/media/design-render/design-render.types';

/**
 * Mutable state shared between the `canvas` mock factory and the tests.
 * Vitest hoists `vi.mock`, so the factory reads this object by reference.
 */
const testState = vi.hoisted(() => ({
  imageDimensions: { width: 100, height: 100 },
  drawImageCalls: [] as Array<{ img: any; args: number[] }>,
  filterAssignments: [] as string[],
  putImageDataCalls: 0,
  canvasInstances: [] as Array<{ width: number; height: number }>,
}));

vi.mock('canvas', () => ({
  createCanvas: vi.fn((width: number, height: number) => {
    testState.canvasInstances.push({ width, height });

    let currentFilter = 'none';
    const filterStack: string[] = [];

    const ctx: any = {
      save: vi.fn(() => filterStack.push(currentFilter)),
      restore: vi.fn(() => {
        currentFilter = filterStack.pop() ?? 'none';
      }),
      scale: vi.fn(),
      translate: vi.fn(),
      rotate: vi.fn(),
      fillRect: vi.fn(),
      strokeRect: vi.fn(),
      clearRect: vi.fn(),
      beginPath: vi.fn(),
      closePath: vi.fn(),
      moveTo: vi.fn(),
      lineTo: vi.fn(),
      arcTo: vi.fn(),
      ellipse: vi.fn(),
      rect: vi.fn(),
      clip: vi.fn(),
      fill: vi.fn(),
      stroke: vi.fn(),
      drawImage: vi.fn((img: any, ...args: number[]) => {
        testState.drawImageCalls.push({ img, args });
      }),
      measureText: vi.fn(() => ({ width: 0 })),
      fillText: vi.fn(),
      strokeText: vi.fn(),
      createLinearGradient: vi.fn(() => ({ addColorStop: vi.fn() })),
      createRadialGradient: vi.fn(() => ({ addColorStop: vi.fn() })),
      // Pixel-space filtering reads the buffer back and writes it again;
      // `putImageData` is therefore the observable "a filter ran" signal.
      getImageData: vi.fn((x: number, y: number, w: number, h: number) => ({
        data: new Uint8ClampedArray(Math.max(1, w * h) * 4),
        width: w,
        height: h,
      })),
      putImageData: vi.fn(() => {
        testState.putImageDataCalls += 1;
      }),
      getTransform: vi.fn(() => ({ a: 1, b: 0, c: 0, d: 1, e: 0, f: 0 })),
      setTransform: vi.fn(),
    };

    Object.defineProperty(ctx, 'filter', {
      get: () => currentFilter,
      set: (value: string) => {
        currentFilter = value;
        testState.filterAssignments.push(value);
      },
    });

    Object.defineProperty(ctx, 'fillStyle', {
      get: () => '',
      set: vi.fn(),
    });

    Object.defineProperty(ctx, 'strokeStyle', {
      get: () => '',
      set: vi.fn(),
    });

    Object.defineProperty(ctx, 'lineWidth', {
      get: () => 1,
      set: vi.fn(),
    });

    Object.defineProperty(ctx, 'globalAlpha', {
      get: () => 1,
      set: vi.fn(),
    });

    Object.defineProperty(ctx, 'globalCompositeOperation', {
      get: () => 'source-over',
      set: vi.fn(),
    });

    Object.defineProperty(ctx, 'font', {
      get: () => '10px sans-serif',
      set: vi.fn(),
    });

    Object.defineProperty(ctx, 'textAlign', {
      get: () => 'left',
      set: vi.fn(),
    });

    Object.defineProperty(ctx, 'textBaseline', {
      get: () => 'top',
      set: vi.fn(),
    });

    Object.defineProperty(ctx, 'shadowColor', {
      get: () => '',
      set: vi.fn(),
    });

    Object.defineProperty(ctx, 'shadowBlur', {
      get: () => 0,
      set: vi.fn(),
    });

    Object.defineProperty(ctx, 'shadowOffsetX', {
      get: () => 0,
      set: vi.fn(),
    });

    Object.defineProperty(ctx, 'shadowOffsetY', {
      get: () => 0,
      set: vi.fn(),
    });

    return {
      getContext: vi.fn(() => ctx),
      toBuffer: vi.fn((format?: string) =>
        Buffer.from(`png:${width}x${height}:${format ?? 'image/png'}`)
      ),
      width,
      height,
    };
  }),
  loadImage: vi.fn(() =>
    Promise.resolve({
      naturalWidth: testState.imageDimensions.width,
      naturalHeight: testState.imageDimensions.height,
      width: testState.imageDimensions.width,
      height: testState.imageDimensions.height,
    })
  ),
  registerFont: vi.fn(),
}));

describe('DesignRenderService', () => {
  let service: DesignRenderService;

  beforeEach(() => {
    testState.imageDimensions = { width: 100, height: 100 };
    testState.drawImageCalls = [];
    testState.filterAssignments = [];
    testState.putImageDataCalls = 0;
    testState.canvasInstances = [];

    service = new DesignRenderService({
      loadOrgFonts: vi.fn(),
      loadCuratedFonts: vi.fn(),
    } as any);
  });

  describe('multi-output sizing', () => {
    it('renders two PNGs sized to each output', async () => {
      const doc: DesignerDoc = {
        version: 1,
        mode: 'image',
        outputs: [
          {
            id: 'o1',
            formatId: 'ig-post',
            name: 'IG Post',
            width: 800,
            height: 600,
            background: '#ff0000',
            children: [],
          },
          {
            id: 'o2',
            formatId: 'x-post',
            name: 'X Post',
            width: 400,
            height: 300,
            background: '#0000ff',
            children: [],
          },
        ],
      };

      const buffers = await service.renderAllPages(doc);

      expect(buffers).toHaveLength(2);
      expect(testState.canvasInstances).toHaveLength(2);
      expect(testState.canvasInstances[0]).toEqual({ width: 800, height: 600 });
      expect(testState.canvasInstances[1]).toEqual({ width: 400, height: 300 });
    });
  });

  describe('cover focal point', () => {
    it('crops a portrait source toward a non-center focal point', async () => {
      // Source is 200x400 (portrait), target is 100x100 (square).
      // srcRatio (0.5) < targetRatio (1) => crop width = full source width,
      // crop height = source width / targetRatio = 200.
      // With focalPoint.y = 0.75, sy = (400 - 200) * 0.75 = 150.
      testState.imageDimensions = { width: 200, height: 400 };

      const doc: DesignerDoc = {
        version: 1,
        mode: 'image',
        outputs: [
          {
            id: 'o1',
            formatId: 'custom',
            name: 'Square crop',
            width: 100,
            height: 100,
            background: '#ffffff',
            children: [
              {
                id: 'img1',
                type: 'image',
                x: 0,
                y: 0,
                width: 100,
                height: 100,
                rotation: 0,
                opacity: 1,
                locked: false,
                hidden: false,
                src: 'data:image/png;base64,placeholder',
                fitMode: 'cover',
                focalPoint: { x: 0.25, y: 0.75 },
              },
            ],
          },
        ],
      };

      await service.renderPage(doc, 0);

      const coverDraw = testState.drawImageCalls.find((c) => c.args.length === 8);
      expect(coverDraw).toBeDefined();

      const [sx, sy, sw, sh, dx, dy, dw, dh] = coverDraw!.args;
      expect(sx).toBe(0);
      expect(sy).toBe(150);
      expect(sw).toBe(200);
      expect(sh).toBe(200);
      expect(dx).toBe(0);
      expect(dy).toBe(0);
      expect(dw).toBe(100);
      expect(dh).toBe(100);
    });
  });

  describe('filter parity', () => {
    it('applies filters in pixel space, never via ctx.filter', async () => {
      // `ctx.filter` is accepted and silently IGNORED by node-canvas — the
      // original implementation assigned it, this test asserted the
      // assignment, and every filter evaporated in every export while the
      // suite stayed green. Filters now run on real pixels
      // (`applyFilterTokensToCanvas`), so the observable contract is a
      // buffer readback/writeback for the filtered image and no `ctx.filter`
      // assignment at all.
      const doc: DesignerDoc = {
        version: 1,
        mode: 'image',
        outputs: [
          {
            id: 'o1',
            formatId: 'custom',
            name: 'Filter test',
            width: 200,
            height: 200,
            background: '#ffffff',
            children: [
              {
                id: 'img1',
                type: 'image',
                x: 0,
                y: 0,
                width: 100,
                height: 100,
                rotation: 0,
                opacity: 1,
                locked: false,
                hidden: false,
                src: 'data:image/png;base64,filtered',
                filters: ['grayscale', 'brightness:1.5'],
              },
              {
                id: 'img2',
                type: 'image',
                x: 100,
                y: 100,
                width: 100,
                height: 100,
                rotation: 0,
                opacity: 1,
                locked: false,
                hidden: false,
                src: 'data:image/png;base64,unfiltered',
              },
            ],
          },
        ],
      };

      await service.renderPage(doc, 0);

      // The filtered image round-tripped through pixels; the unfiltered one
      // must not pay for that.
      expect(testState.putImageDataCalls).toBe(1);
      expect(testState.filterAssignments).toEqual([]);
      // Both images still drew — a filter failing must never drop the layer.
      const drawn = testState.drawImageCalls.filter((c) => c.img && typeof c.img === 'object');
      expect(drawn.length).toBeGreaterThanOrEqual(2);
    });
  });
});

import { describe, it, expect } from 'vitest';
import { AuthService } from './auth.service';

describe('AuthService.fixedDecryption', () => {
  it('throws a distinct error for empty values (not the legacy-CBC message)', () => {
    expect(() => AuthService.fixedDecryption('')).toThrow(
      'AuthService.fixedDecryption: cannot decrypt an empty value'
    );
    expect(() => AuthService.fixedDecryption(undefined as any)).toThrow(
      'AuthService.fixedDecryption: cannot decrypt an empty value'
    );
    expect(() => AuthService.fixedDecryption(null as any)).toThrow(
      'AuthService.fixedDecryption: cannot decrypt an empty value'
    );
  });

  it('refuses non-v2: values', () => {
    expect(() => AuthService.fixedDecryption('legacy-cbc-value')).toThrow(
      'refusing to decrypt a value that is not `v2:`-encrypted'
    );
  });

  it('round-trips fixedEncryption -> fixedDecryption', () => {
    const secret = '[REDACTED]';
    const encrypted = AuthService.fixedEncryption(secret);
    expect(encrypted.startsWith('v2:')).toBe(true);
    expect(AuthService.fixedDecryption(encrypted)).toBe(secret);
  });
});

import { describe, it, expect, vi } from 'vitest';
import {
  AiDesignerInputPolicyService,
  GuardedInput,
} from './ai-designer-input-policy.service';
import { GuardrailViolation } from '@postmill-ai/nestjs-libraries/ai/governance/errors';

const makeService = (
  guardrailImpl: (text: string, orgId?: string) => Promise<string> = async (
    text
  ) => text
) => {
  const service = {
    applyGuardrails: vi.fn(guardrailImpl),
  } as any;
  return { policy: new AiDesignerInputPolicyService(service), service };
};

const ORG_ID = 'org-1';

describe('AiDesignerInputPolicyService', () => {
  it('passes a clean string through the guardrail', async () => {
    const { policy, service } = makeService();
    const result = await policy.check(
      { values: {}, instruction: 'hello world' },
      ORG_ID
    );
    expect(result).toEqual({ ok: true, values: {}, instruction: 'hello world' });
    expect(service.applyGuardrails).toHaveBeenCalledWith('hello world', ORG_ID);
  });

  it('returns guardrail_blocked when the instruction is blocked', async () => {
    const { policy, service } = makeService(() => {
      throw new GuardrailViolation('blocked', 'policy-1', 'block');
    });
    const result = await policy.check(
      { values: {}, instruction: 'bad text' },
      ORG_ID
    );
    expect(result).toEqual({
      ok: false,
      reason: 'guardrail_blocked',
      message: 'blocked',
    });
    expect(service.applyGuardrails).toHaveBeenCalledWith('bad text', ORG_ID);
  });

  it('recursively guards nested strings inside values', async () => {
    const { policy, service } = makeService();
    const input: GuardedInput = {
      values: {
        intent: 'a promo',
        details: {
          audience: 'devs',
          tags: ['foo', 'bar'],
        },
      },
    };
    const result = await policy.check(input, ORG_ID);
    expect(result.ok).toBe(true);
    expect((result as any).values).toEqual({
      intent: 'a promo',
      details: {
        audience: 'devs',
        tags: ['foo', 'bar'],
      },
    });
    expect(service.applyGuardrails).toHaveBeenCalledWith('a promo', ORG_ID);
    expect(service.applyGuardrails).toHaveBeenCalledWith('devs', ORG_ID);
    expect(service.applyGuardrails).toHaveBeenCalledWith('foo', ORG_ID);
    expect(service.applyGuardrails).toHaveBeenCalledWith('bar', ORG_ID);
  });

  it('returns guardrail_blocked for a nested blocked string', async () => {
    const { policy, service } = makeService((text) => {
      if (text === 'bad nested') {
        throw new GuardrailViolation('nested blocked', 'policy-1', 'block');
      }
      return text;
    });
    const input: GuardedInput = {
      values: {
        outer: {
          inner: 'bad nested',
        },
      },
    };
    const result = await policy.check(input, ORG_ID);
    expect(result).toEqual({
      ok: false,
      reason: 'guardrail_blocked',
      message: 'nested blocked',
    });
    expect(service.applyGuardrails).toHaveBeenCalledWith('bad nested', ORG_ID);
  });

  it('returns value_bounds when byte size exceeds the cap', async () => {
    const { policy, service } = makeService();
    const input: GuardedInput = {
      values: {
        blob: 'x'.repeat(40_000),
      },
    };
    const result = await policy.check(input, ORG_ID);
    expect(result).toEqual({
      ok: false,
      reason: 'value_bounds',
      message: expect.stringContaining('32'),
    });
    expect(service.applyGuardrails).not.toHaveBeenCalled();
  });

  it('returns value_bounds for circular values instead of crashing', async () => {
    const { policy, service } = makeService();
    const circular: Record<string, unknown> = { v: 'leaf' };
    circular.self = circular;
    const result = await policy.check({ values: circular }, ORG_ID);
    expect(result).toEqual({
      ok: false,
      reason: 'value_bounds',
      message: expect.stringContaining('size or depth limits'),
    });
    expect(service.applyGuardrails).not.toHaveBeenCalled();
  });

  it('returns value_bounds when nesting depth exceeds the cap', async () => {
    const { policy, service } = makeService();
    const deep: Record<string, unknown> = { v: 'leaf' };
    let current: Record<string, unknown> = deep;
    for (let i = 0; i < 6; i++) {
      const next: Record<string, unknown> = { v: 'leaf' };
      current.nested = next;
      current = next;
    }
    const result = await policy.check({ values: deep }, ORG_ID);
    expect(result).toEqual({
      ok: false,
      reason: 'value_bounds',
      message: expect.stringContaining('depth'),
    });
    expect(service.applyGuardrails).not.toHaveBeenCalled();
  });

  it('returns invalid_key for keys outside the allowed character set', async () => {
    const { policy, service } = makeService();
    const result = await policy.check(
      { values: { 'intent<script>': 'x' } },
      ORG_ID
    );
    expect(result).toEqual({
      ok: false,
      reason: 'invalid_key',
      message: expect.stringContaining('intent<script>'),
    });
    expect(service.applyGuardrails).not.toHaveBeenCalled();
  });

  it('returns invalid_key for keys longer than 64 characters', async () => {
    const { policy, service } = makeService();
    const longKey = 'a'.repeat(65);
    const result = await policy.check({ values: { [longKey]: 'x' } }, ORG_ID);
    expect(result).toEqual({
      ok: false,
      reason: 'invalid_key',
      message: expect.stringContaining(longKey),
    });
    expect(service.applyGuardrails).not.toHaveBeenCalled();
  });

  it('rejects keys containing spaces', async () => {
    const { policy, service } = makeService();
    const result = await policy.check(
      { values: { 'user key': 'value' } },
      ORG_ID
    );
    expect(result).toEqual({
      ok: false,
      reason: 'invalid_key',
      message: expect.stringContaining('user key'),
    });
    expect(service.applyGuardrails).not.toHaveBeenCalled();
  });

  it('passes an empty instruction without calling guardrails', async () => {
    const { policy, service } = makeService();
    const result = await policy.check({ values: {} }, ORG_ID);
    expect(result).toEqual({ ok: true, values: {} });
    expect(service.applyGuardrails).not.toHaveBeenCalled();
  });

  it('redacts an instruction returned by the guardrail', async () => {
    const { policy, service } = makeService((text) => text.replace(/secret/, '[REDACTED]'));
    const result = await policy.check(
      { values: {}, instruction: 'top secret plan' },
      ORG_ID
    );
    expect(result).toEqual({
      ok: true,
      values: {},
      instruction: 'top [REDACTED] plan',
    });
  });
});

import { describe, it, expect, vi, beforeEach } from 'vitest';

